hand = '4S 5H 4C 8D 4H'

    def score_hand(hand):
        """Return a comparable score tuple for a five-card hand.

        The first element is the hand category; the remaining elements are
        tie-breaker ranks, most significant first.
        """
        ranks, suits = _parse(hand)

        is_flush = len(set(suits)) == 1

        counts = {}
        for rank in ranks:
            counts[rank] = counts.get(rank, 0) + 1
        # Group by (count, rank), highest first: e.g. a full house of
        # 5s and 9s yields [(5, 3), (9, 2)].
        groups = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)

        straight_high = None
        if len(set(ranks)) == 5:
            if max(ranks) - min(ranks) == 4:
                straight_high = max(ranks)
            elif set(ranks) == {2, 3, 4, 5, 14}:
                # A-2-3-4-5 is a "wheel": the lowest straight.
                straight_high = 5

        if is_flush and straight_high is not None:
            return (STRAIGHT_FLUSH, straight_high)
        if is_flush:
            return (FLUSH, *sorted(ranks, reverse=True))
        if straight_high is not None:
            return (STRAIGHT, straight_high)

        if groups[0][1] == 4:
            return (FOUR_OF_A_KIND, *[rank for rank, _ in groups])
        if groups[0][1] == 3:
            if groups[1][1] == 2:
                return (FULL_HOUSE, *[rank for rank, _ in groups])
>           return (THREE_OF_A_KIND, *[rank for rank, _ in groups])
